import java.util.*;

class Solution {
    private int best = Integer.MIN_VALUE;

    public int maxPathSum(TreeNode root) {
        arm(root);
        return best;
    }

    // best sum of a path that starts at n and goes straight down
    private int arm(TreeNode n) {
        if (n == null) return 0;
        int l = Math.max(0, arm(n.left));   // drop arms that only hurt
        int r = Math.max(0, arm(n.right));
        best = Math.max(best, n.val + l + r); // path bending at n
        return n.val + Math.max(l, r);       // parent can use one side only
    }
}

