class Solution:
    def maxPathSum(self, root: Optional[TreeNode]) -> int:
        best = -inf
        def arm(n):
            nonlocal best
            if not n: return 0
            a, b = max(0, arm(n.left)), max(0, arm(n.right))
            best = max(best, n.val + a + b)
            return n.val + max(a, b)
        arm(root)
        return best

